(() => {
  'use strict';
  // Version 11 (Claude studio). Behaviour adapted from version 10; markup rebuilt for the reading-room design.
  const KEY='lsatu-claude-studio-v1';
  const applePlatform=/Mac|iPhone|iPad|iPod/i.test(navigator.userAgentData?.platform||navigator.platform||'');
  const shortcutLabel=applePlatform?'⌘ K':'Ctrl K';
  const shortcutKeys=applePlatform?'Meta+K':'Control+K';
  const $=(s,r=document)=>r.querySelector(s);
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icons={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3z',work:'M6 5h12v16H6z M9 5V3h6v2 M9 10h6 M9 14h6',practice:'m14 3 7 7-11 11H3v-7z M11 6l7 7',review:'M4 7V3m0 4h4 M4 7a9 9 0 1 1-1 9 M12 7v5l3 2',progress:'M4 20V12 M10 20V8 M16 20V4 M22 20H2',library:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3z M12 6v16',reading:'M4 5h6a2 2 0 0 1 2 2v13a2 2 0 0 0-2-2H4z M20 5h-6a2 2 0 0 0-2 2v13a2 2 0 0 1 2-2h6z',messages:'M3 4h18v13H8l-5 4z M7 8h10 M7 12h7',search:'M20 20l-5-5 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',arrow:'M5 12h14 M13 6l6 6-6 6',back:'M19 12H5 M11 6l-6 6 6 6',close:'m6 6 12 12 M6 18 18 6',teacher:'M3 3h18v13H3z M12 16v5 M7 21h10 M7 8h4 M7 12h9',students:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M13 3a4 4 0 1 1 0 8 M22 21v-3a4 4 0 0 0-3-4 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',bookmark:'M6 3h12v18l-6-4-6 4z',check:'m5 12 4 4L19 6',timer:'M12 8v5l3 2 M9 2h6 M12 22a9 9 0 1 0 0-18 9 9 0 0 0 0 18',drill:'M4 6h16 M4 12h10 M4 18h6 M17 15l3 3-3 3'};
  const ico=n=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[n]||icons.arrow}"/></svg>`;
  const assignments=[{id:'negation',title:'Negation Station',type:'LR',detail:'Activity · 12 statements',status:'Saved at statement 6 · 5 of 12 complete',description:'Rewrite one statement at a time so that it says the opposite. Keep the scope of the original statement in view.'},{id:'flaw',title:'Find the flaw',type:'LR',detail:'Practice set · 8 questions',status:'Assigned 2026-10-23 · Not started',description:'Read each argument, identify its conclusion, then explain the gap between its evidence and conclusion.'},{id:'recall',title:'Reading recall',type:'RC',detail:'Activity · One paragraph at a time',status:'Assigned 2026-10-23 · Not started',description:'Read a paragraph, set it aside, and recall its main point in your own words. Return to the paragraph to check what you missed.'},{id:'conditional',title:'Conditional Indicators Refresher',type:'LR',detail:'Bootcamp · Conditional language',status:'Assigned 2026-10-22 · Not started',description:'Use the signal words to identify what is sufficient and what is necessary. Preserve the complete conditions in your rewrite.'}];
  const questions=[
    {id:'lr155',title:'The longer opening hours',type:'LR',pt:'155',section:'1',number:'1',text:'A library extended its opening hours in June. Visits increased that month. The director concludes that extending the opening hours caused the increase in visits.',prompt:'Which possibility most directly calls the director’s explanation into question?',answers:['The library offered a popular new summer programme in June.','Some visitors borrowed more than one book.','The director prefers the new opening hours.'],correct:0,hints:['Consider whether another change could explain the increase.','Borrowing several books does not explain why more people visited. Look for another cause of the increased visits.','The director’s preference does not explain the increase in visits. Look for a competing cause.'],explanation:'The summer programme provides another possible cause of the increased visits. It does not prove the longer hours had no effect, but it weakens the claim that they explain the increase.'},
    {id:'rc155',title:'A record of a changing landscape',type:'RC',pt:'155',section:'3',number:'5',text:'For years, researchers treated old field sketches as illustrations of landscapes rather than as data. A recent comparison found that several sketches accurately recorded the location of a river before it changed course. The sketches cannot establish the river’s exact depth, but they may help reconstruct its former path.',prompt:'Which statement best captures the paragraph’s main point?',answers:['Old sketches reveal every feature of a river’s history.','Some old sketches may provide evidence of a river’s former course.','Researchers should stop collecting modern river data.'],correct:1,hints:['“Every feature” goes beyond the paragraph. Notice the limit about depth and try again.','The claim is limited to some sketches and the former course.','The paragraph discusses an additional source of evidence. Does it recommend abandoning modern data?'],explanation:'The paragraph argues for a limited use of the sketches as evidence of a former path. It explicitly says they cannot establish exact depth.'},
    {id:'lr154',title:'Who may enter the archive?',type:'LR',pt:'154',section:'2',number:'14',text:'Only researchers with a valid permit may enter the archive. Mira entered the archive in accordance with this rule.',prompt:'What must follow from these statements?',answers:['Every researcher with a valid permit enters the archive.','Mira has a valid permit.','Mira is the only researcher who entered the archive.'],correct:1,hints:['A permit is required for entry. Does having a permit guarantee that someone enters?','Entry in accordance with the rule requires the permit.','The rule restricts entry by permit status. Does it limit the number of people who enter?'],explanation:'The permit is a necessary condition for permitted entry. Because Mira entered in accordance with the rule, she has a valid permit. The rule does not say that everyone with a permit enters.'}
  ];
  questions.push(
    {id:'lr156',title:'The museum survey',type:'LR',pt:'156',section:'2',number:'7',text:'A museum surveyed people leaving its special exhibition. Most respondents wanted more exhibitions about sculpture. The curator concludes that most residents of the city want more sculpture exhibitions.',prompt:'What is the main weakness in the curator’s reasoning?',answers:['Visitors to this exhibition may not represent the city’s residents.','The survey proves that no residents enjoy paintings.','The curator did not name the sculptors.'],correct:0,hints:['Compare the group surveyed with the group in the conclusion.','Wanting more sculpture does not show that anyone dislikes paintings. Compare the two groups.','Naming artists would not establish what city residents want. Compare the surveyed group with the conclusion’s group.'],explanation:'The survey describes people who attended this exhibition. They may have a stronger interest in sculpture than residents generally. Without a reason to treat these visitors as representative, the conclusion goes beyond the evidence.'},
    {id:'rc156',title:'What the seed archive preserves',type:'RC',pt:'156',section:'3',number:'9',text:'Seed archives are often described as collections of crop varieties. Yet preserving seeds alone does not preserve every practice used to grow them. Some varieties depend on techniques passed between farmers. Archives can protect important biological material, while partnerships with farming communities can help retain the knowledge needed to use it.',prompt:'Why does the author mention techniques passed between farmers?',answers:['To show that storing seeds makes farming communities unnecessary.','To explain why seed storage can benefit from preserving practical knowledge as well.','To argue that archives cannot protect biological material.'],correct:1,hints:['The passage gives farming communities an ongoing role. What do they preserve that a stored seed cannot?','The techniques supply knowledge about using the preserved material.','The author explicitly credits archives with protecting biological material. Consider what partnerships add.'],explanation:'The techniques illustrate a kind of knowledge that storing seeds does not by itself preserve. That supports the limited recommendation to combine biological preservation with community knowledge, rather than to abandon archives.'}
  );
  const attempts=[{id:'lr155',correct:true,date:'October 23, 2026'},{id:'lr154',correct:true,date:'October 23, 2026'},{id:'lr156',correct:false,date:'October 23, 2026'},{id:'rc155',correct:true,date:'October 22, 2026'},{id:'rc156',correct:false,date:'October 22, 2026'}];
  const totals={answered:attempts.length,correct:attempts.filter(a=>a.correct).length,sets:new Set(attempts.map(a=>a.date)).size};
  const attemptDates=attempts.map(a=>new Date(a.date+' 12:00:00')).sort((a,b)=>a-b);
  const dateLabel=d=>d.toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'});
  const attemptDateRange=dateLabel(attemptDates[0])+' to '+dateLabel(attemptDates.at(-1));
  const students=[{name:'Ada Williams',focus:'Conditional language',next:'Oct 26 · 7:15 p.m.',work:'4 assigned'},{name:'Noah Chen',focus:'Argument structure',next:'Oct 27 · 4:00 p.m.',work:'2 assigned'},{name:'Imani Brooks',focus:'Reading recall',next:'Oct 28 · 6:00 p.m.',work:'3 assigned'},{name:'Leo Martin',focus:'Necessary assumptions',next:'Oct 29 · 5:30 p.m.',work:'1 assigned'}];
  const week=[['Sat','Saturday'],['Sun','Sunday'],['Mon','Monday'],['Tue','Tuesday'],['Wed','Wednesday'],['Thu','Thursday'],['Fri','Friday']];
  let stored={},storageOK=true,storedText=null;
  try{storedText=localStorage.getItem(KEY);}catch{storageOK=false;}
  if(storedText){try{stored=JSON.parse(storedText);if(!stored||typeof stored!=='object'||Array.isArray(stored))stored={};}catch{stored={};}}
  const state={role:stored.role==='teacher'?'teacher':'student',read:stored.read===true,bookmarks:Array.isArray(stored.bookmarks)?stored.bookmarks.filter(x=>questions.some(q=>q.id===x)):[],recent:Array.isArray(stored.recent)?stored.recent.filter(x=>questions.some(q=>q.id===x)):[],note:typeof stored.note==='string'?stored.note:'',draft:typeof stored.draft==='string'?stored.draft:'',workingDraft:typeof stored.draft==='string'?stored.draft:'',draftDirty:false,draftSaveError:false,noteWorking:null,negationWorking:null,day:24,workFilter:'All',workStatus:'All',workQuery:'',questionType:'All',reviewFilter:'All',library:'Lessons',query:'',studentQuery:'',question:null,answer:null,checked:false,questionTab:'All',resumeId:'negation',storageError:!storageOK};
  const main=$('#main'),modal=$('#modal'),drawer=$('#drawer');let dialogTrigger=null,toastTimer,escArmed=false;
  function toast(message){clearTimeout(toastTimer);$('#status').textContent=message;toastTimer=setTimeout(()=>{$('#status').textContent='';},6500);}
  function save(patch){const next={role:state.role,read:state.read,bookmarks:state.bookmarks,recent:state.recent,note:state.note,draft:state.draft,...patch};try{localStorage.setItem(KEY,JSON.stringify(next));Object.assign(state,patch);state.storageError=false;return true;}catch{state.storageError=true;toast('This browser could not save locally. Your changes remain here until you leave this preview.');return false;}}

  function navHTML(inDrawer=false){
    const role=state.role==='teacher';
    const routes=role?[['teacher','Teacher home','teacher'],['students','Students','students']]:[['home','Home','home'],['work','My Work','work'],['practice','Practice','practice'],['review','Review','review'],['progress','Progress','progress'],['library','Library','library'],['reading','Reading Center','reading']];
    const route=currentRoute();
    const link=(r,t,i,extra='')=>`<a class="navlink ${route===r?'active':''}" href="#${r}" ${extra} ${route===r?'aria-current="page"':''}>${ico(i)}<span>${t}</span></a>`;
    return `<a class="brand" href="#${role?'teacher':'home'}"><span class="brandmark" aria-hidden="true">U</span><span class="brandname">LSAT U</span></a>
      <nav aria-label="${role?'Teaching':'Classroom'}"><div class="navlabel">${role?'Teaching preview':'Your classroom'}</div>${routes.map(([r,t,i])=>link(r,t,i,r==='practice'?'data-action="finder"':'')).join('')}
      ${!role?`<div class="navlabel">Quick access</div><a class="navlink ${route==='messages'?'active':''}" href="#messages" ${route==='messages'?'aria-current="page"':''}>${ico('messages')}<span>Messages</span>${!state.read?'<span class="badge" aria-label="1 unread message">1</span>':''}</a><a class="navlink" href="#practice" data-action="finder">${ico('search')}<span>Find a question</span></a>`:''}</nav>
      <div class="sidebar-foot"><div class="identity"><span class="avatar">${role?'JF':'AW'}</span><div><strong>${role?'Joshua Fisseha':'Ada Williams'}</strong><small>${role?'Sample teacher workspace':'Student preview'}</small></div></div><label for="${inDrawer?'drawer-role':'role-select'}">Preview workspace</label><select id="${inDrawer?'drawer-role':'role-select'}" data-action="role"><option value="student" ${!role?'selected':''}>Student</option><option value="teacher" ${role?'selected':''}>Teacher</option></select></div>`;
  }
  function renderNav(){$('#sidebar').innerHTML=navHTML();}
  function currentRoute(){return location.hash.slice(1).split('?')[0]||(state.role==='teacher'?'teacher':'home');}
  function footer(){return `<footer class="preview-footer"><span>Local design preview · Sample people, assignments and questions</span><span>No connection to your LSAT U account</span></footer>`;}
  function storageWarning(){return state.storageError?'<p class="storage-warning" role="status">Local saving is unavailable. Saved states may not survive closing this preview.</p>':'';}
  function intro(label,title,desc){return `<header class="page-intro"><div class="eyebrow">${label}</div><h1 id="page-title" tabindex="-1">${title}</h1><p>${desc}</p></header>`;}

  // Twelve numbered statement cells. Done, next and remaining are distinguished by fill, outline and numeral weight, not colour alone.
  function statementTrack(theme=''){return `<div class="statement-track ${theme}" role="img" aria-label="5 of 12 statements complete. Statement 6 is next.">${Array.from({length:12},(_,i)=>`<span class="${i<5?'done':i===5?'next':''}" style="--n:${i}">${i+1}</span>`).join('')}</div>`;}
  function isInProgress(a){return a.id==='negation';}
  function assignmentRows(list,numbered=false){return list.length?list.map((a,i)=>{const live=isInProgress(a);return `<article class="assignment ${live?'is-current':''}">${numbered?`<span class="ledger-no" aria-hidden="true">${String(i+1).padStart(2,'0')}</span>`:''}<span class="work-type ${a.type==='RC'?'rc':'lr'}" title="${a.type==='RC'?'Reading Comprehension':'Logical Reasoning'}">${a.type}</span><div class="assignment-body"><h3>${a.title}</h3><p>${a.detail}</p><div class="work-meta"><span class="work-state ${live?'in-progress':''}">${live?'In progress · 5 of 12':'Not started'}</span><span>Assigned ${a.id==='conditional'?'Oct 22':'Oct 23'}</span></div>${live?'<span class="meter" aria-hidden="true"><i style="width:41.67%"></i></span>':''}</div><button data-action="assignment" data-id="${a.id}" aria-label="Open ${a.title}">Open ${ico('arrow')}</button></article>`;}).join(''):'<p class="empty">No assignments match these filters. Try another subject, status or title.</p>';}
  function coachMessage(){return `<div class="message"><span class="avatar coach-avatar">JF</span><div class="message-body"><div class="message-meta"><strong>Joshua</strong>${!state.read?'<span class="unread-dot" aria-label="Unread"></span>':''}<time datetime="2026-10-24T14:20:00-04:00">Oct 24 · 2:20 p.m.</time></div><blockquote>On your next pass, say what has to be true before you look at the answer choices.</blockquote><p class="task-note">About <a href="#work" data-action="assignment" data-id="conditional">Conditional Indicators Refresher</a></p><div class="message-actions"><button class="text-button" data-action="reply">Reply ${ico('arrow')}</button>${!state.read?'<button class="text-button quiet-button" data-action="read">Mark as read</button>':'<span class="quiet">Read</span>'}</div></div></div>`;}
  function coachCard(){return `<section class="card coach" aria-labelledby="coach-title"><header class="card-head"><h2 id="coach-title">From your coach</h2><span class="count ${state.read?'':'is-new'}">${state.read?'All read':'1 new'}</span></header>${coachMessage()}</section>`;}
  function sessionCard(){return `<section class="card session" aria-labelledby="session-title"><header class="card-head"><h2 id="session-title">Your next session</h2><span class="quiet">Eastern time</span></header><div class="session-when"><p class="session-time"><strong>7:15</strong> p.m.</p><p class="session-day"><span>Monday, October 26</span><span>60 minutes with Joshua</span></p></div>${state.note?`<p class="prep-preview"><strong>Your preparation</strong>${esc(state.note)}</p>`:''}<button class="secondary" data-action="prepare">${state.note?'Edit preparation':'Prepare a note'} ${ico('arrow')}</button></section>`;}
  function home(){const unread=!state.read;return `
    <section class="desk-head">
      <div class="greeting"><p class="dateline">Saturday, October 24, 2026</p><h1 id="page-title" tabindex="-1">Good evening, Ada.</h1><p class="summary">You have <strong>4 open assignments</strong>${unread?' and <strong>1 unread note</strong> from Joshua':''}. Your next session is Monday at 7:15 p.m.</p></div>
      <div class="head-tools"><button class="finder" data-action="finder" aria-keyshortcuts="${shortcutKeys}">${ico('search')}<span>Find a question</span><kbd>${shortcutLabel}</kbd></button><div class="quick-actions" role="group" aria-label="Quick actions"><button data-action="quick-practice" data-mode="drill">${ico('drill')}Smart Drill</button><button data-action="quick-practice" data-mode="timed">${ico('timer')}Timed section</button><a href="#messages">${ico('messages')}Inbox${unread?'<span class="badge" aria-label="1 unread">1</span>':''}</a></div></div>
    </section>
    <section class="desk" aria-label="Today">
      <article class="resume" aria-labelledby="resume-title">
        <div class="resume-art" aria-hidden="true"></div>
        <div class="resume-copy">
          <p class="resume-kicker"><span class="work-type lr on-night">LR</span>Pick up where you stopped</p>
          <h2 id="resume-title">Negation Station</h2>
          <figure class="next-statement"><figcaption>Statement 6 of 12 · your next one</figcaption><blockquote>Some of the books are illustrated.</blockquote></figure>
          <p class="resume-instruction">Write the opposite. Change only what you need to make it false.</p>
          ${statementTrack('on-night')}
          <div class="resume-actions"><button class="lamp" data-action="continue">Continue at statement 6 ${ico('arrow')}</button><span class="resume-progress">5 of 12 complete</span></div>
        </div>
      </article>
      <div class="desk-side">${coachCard()}${sessionCard()}</div>
    </section>
    <section class="desk-lower">
      <section class="card ledger" aria-labelledby="ledger-title"><header class="card-head"><h2 id="ledger-title">Assigned to you</h2><a class="head-link" href="#work">All in My Work ${ico('arrow')}</a></header>${assignmentRows(assignments,true)}</section>
      <section class="card week" aria-labelledby="week-title"><header class="card-head"><h2 id="week-title">Next seven days</h2><span class="quiet">Oct 24 to 30 · Sample week</span></header><div class="days" role="tablist" aria-label="Select a day">${daysHTML()}</div><div id="agenda" class="agenda" role="tabpanel">${agendaHTML()}</div></section>
    </section>`;}
  function daysHTML(){return week.map(([d,full],i)=>{const n=i+24,sel=state.day===n;return `<button class="day ${i===2?'has-session':''} ${i===0?'is-today':''}" role="tab" id="day-${n}" aria-controls="agenda" aria-selected="${sel}" tabindex="${sel?0:-1}" data-action="day" data-day="${n}" aria-label="${full} October ${n}${i===0?', today':''}${i===2?', session at 7:15 p.m.':''}"><span class="day-name">${d}</span><span class="day-num">${n}</span><span class="day-note">${i===2?'<span class="eventdot"></span>Session 7:15':i===0?'Today':'No session'}</span></button>`;}).join('');}
  function agendaHTML(){const full=week[state.day-24][1];return state.day===26?`<p><strong>Monday, October 26 · 7:15 p.m.</strong><span>Session with Joshua · 60 minutes</span></p><button class="text-button" data-action="prepare">Prepare a note ${ico('arrow')}</button>`:`<p><strong>${full}, October ${state.day}</strong><span>No session scheduled. Work at your own pace.</span></p><a class="text-link" href="#work">View your assignments ${ico('arrow')}</a>`;}
  function selectDay(n){state.day=n;$('.days').innerHTML=daysHTML();const agenda=$('#agenda');agenda.innerHTML=agendaHTML();agenda.setAttribute('aria-labelledby',`day-${n}`);agenda.classList.remove('agenda-change');void agenda.offsetWidth;agenda.classList.add('agenda-change');$(`#day-${n}`).focus();}

  function workResults(){return assignments.filter(a=>(state.workFilter==='All'||a.type===state.workFilter)&&(state.workStatus==='All'||(isInProgress(a)?'In progress':'Not started')===state.workStatus)&&a.title.toLowerCase().includes(state.workQuery.toLowerCase()));}
  function work(){return `${intro('Your classroom','My Work','Your assignments, with your saved place kept intact.')}<div class="work-toolbar"><div class="tabs" aria-label="Filter assignments by subject">${['All','LR','RC'].map(t=>`<button data-action="work-filter" data-value="${t}" aria-pressed="${state.workFilter===t}">${t==='All'?'All subjects':t==='LR'?'Logical Reasoning':'Reading Comprehension'}</button>`).join('')}</div><div class="tabs status-tabs" aria-label="Filter assignments by status">${['All','In progress','Not started'].map(t=>`<button data-action="work-status" data-value="${t}" aria-pressed="${state.workStatus===t}">${t==='All'?'Every status':t}</button>`).join('')}</div><div class="question-search">${ico('search')}<label class="sr-only" for="work-query">Search assignment titles</label><input id="work-query" value="${esc(state.workQuery)}" placeholder="Find an assignment by title"></div></div><section class="card work-list" id="work-results" aria-live="polite">${assignmentRows(workResults())}</section><p class="hint section-space">Local assignment previews. Your saved resume task stays Negation Station.</p>`;}
  function reference(q){return `PT ${q.pt} · Section ${q.section} · Question ${q.number}`;}
  function resultsHTML(list){return list.length?list.map(q=>`<article class="question-row"><span class="work-type ${q.type==='RC'?'rc':'lr'}">${q.type}</span><div class="question-row-body"><h3>${q.title}</h3><p class="ref">${reference(q)}</p><p class="synthetic-note">Original sample. Synthetic question, not the real PT${q.pt} item.</p></div><button data-action="question" data-id="${q.id}">Open question ${ico('arrow')}</button></article>`).join(''):'<p class="empty">No questions match this collection and subject. Try All, change the subject, or search another title or reference.</p>';}
  function filteredQuestions(){let list=questions;if(state.questionTab==='Saved')list=list.filter(q=>state.bookmarks.includes(q.id));if(state.questionTab==='Recent')list=state.recent.map(id=>questions.find(q=>q.id===id)).filter(Boolean);if(state.questionType!=='All')list=list.filter(q=>q.type===state.questionType);const q=state.query.trim().toLowerCase();const exact=parseReference(q);if(exact)return list.filter(x=>x.pt===exact[0]&&x.section===exact[1]&&x.number===exact[2]);return list.filter(x=>[x.title,reference(x),x.type].join(' ').toLowerCase().includes(q)||(`pt${x.pt}s${x.section}q${x.number}${x.type}`.toLowerCase().includes(q.replace(/preptest/g,'pt').replace(/section/g,'s').replace(/question/g,'q').replace(/[^a-z0-9]/g,''))));}
  function practice(){if(state.question)return questionPage();return `${intro('Practice','Find a question','Look up an exact reference, or return to a saved question. Five synthetic questions demonstrate lookup. These references do not retrieve real PrepTest content.')}<div class="practice-layout"><section class="card reference-console"><h2>Find by reference</h2><form id="typed-reference-form"><label for="typed-reference">Exact reference</label><input id="typed-reference" class="ref-input" name="reference" placeholder="PT155 S1 Q1" autocomplete="off" required><button class="primary" type="submit">Open exact reference ${ico('arrow')}</button><p id="typed-reference-feedback" aria-live="polite"></p></form><details class="reference-fields"><summary>Use separate fields</summary><form id="reference-form"><div class="field-grid"><div><label for="ref-type">Question type</label><select id="ref-type" name="type"><option>LR</option><option>RC</option></select></div><div><label for="ref-pt">PrepTest</label><input id="ref-pt" name="pt" inputmode="numeric" placeholder="155" required></div><div><label for="ref-section">Section</label><input id="ref-section" name="section" inputmode="numeric" placeholder="1" required></div><div><label for="ref-question">Question</label><input id="ref-question" name="number" inputmode="numeric" placeholder="1" required></div></div><button class="primary" type="submit">Find question ${ico('arrow')}</button><div id="reference-feedback" aria-live="polite"></div></form></details><div class="sample-references"><span class="eyebrow">Try an original sample</span>${questions.map(q=>`<button data-action="sample-reference" data-id="${q.id}"><span class="work-type ${q.type==='RC'?'rc':'lr'}">${q.type}</span><span class="ref">PT${q.pt} S${q.section} Q${q.number}</span></button>`).join('')}</div></section><section class="question-collection"><div class="question-search">${ico('search')}<label class="sr-only" for="question-query">Search sample titles or references</label><input id="question-query" placeholder="Search by title or reference" value="${esc(state.query)}"></div><div class="collection-controls"><div class="tabs" aria-label="Question collection">${['All','Saved','Recent'].map(t=>`<button data-action="question-tab" data-value="${t}" aria-pressed="${state.questionTab===t}">${t}${t==='Saved'?` · ${state.bookmarks.length}`:''}</button>`).join('')}</div><div class="tabs subject-tabs" aria-label="Question subject">${['All','LR','RC'].map(t=>`<button data-action="question-type" data-value="${t}" aria-pressed="${state.questionType===t}">${t==='All'?'All subjects':t}</button>`).join('')}</div></div><div id="question-results" class="card results-card" aria-live="polite">${resultsHTML(filteredQuestions())}</div></section></div>`;}
  function questionPage(){const q=questions.find(q=>q.id===state.question);return `${intro('Practice · Synthetic sample',q.title,`<span class="ref">${reference(q)}</span>`)}<p class="synthetic-banner">Synthetic question, not the real PT${q.pt} item. This reference demonstrates lookup only.</p><div class="inline-actions question-tools"><button class="text-button" data-action="question-back">${ico('back')}Back to question lookup</button><button data-action="bookmark" data-id="${q.id}" aria-pressed="${state.bookmarks.includes(q.id)}">${ico('bookmark')}${state.bookmarks.includes(q.id)?'Saved':'Save question'}</button></div><div class="question-sheet card"><p class="question-content">${q.text}</p><h2 class="question-prompt">${q.prompt}</h2><form id="answer-form"><fieldset class="bare"><legend class="sr-only">Choose an answer</legend><div class="answers">${q.answers.map((a,i)=>`<label class="answer"><input type="radio" name="answer" value="${i}" ${state.answer===i?'checked':''} required><b>${String.fromCharCode(65+i)}</b><span>${a}</span></label>`).join('')}</div></fieldset><button class="primary" type="submit">Check answer ${ico('arrow')}</button><div id="answer-feedback" aria-live="polite">${state.checked?feedbackHTML(q):''}</div></form></div><p class="hint">Sample interaction only. Answers here do not change your progress or establish mastery.</p>`;}
  function feedbackHTML(q){return state.answer===q.correct?`<div class="feedback is-right"><strong>This answer fits the reasoning.</strong><p>${q.explanation}</p></div>`:`<div class="feedback"><strong>Look again.</strong><p>${q.hints[state.answer]}</p><button class="text-button" data-action="retry">Try another answer ${ico('arrow')}</button></div>`;}
  function review(){return `${intro('Your classroom','Review','Five original questions. Return to the exact reasoning behind each result.')}<div class="review-summary"><strong>${totals.correct} of ${totals.answered} correct</strong><span>${totals.sets} completed sample sets · ${totals.answered-totals.correct} questions to revisit</span></div><div class="tabs" aria-label="Filter review">${['All','Missed'].map(t=>`<button data-action="review-filter" data-value="${t}" aria-pressed="${state.reviewFilter===t}">${t==='All'?'All results':'Missed only'}</button>`).join('')}</div>${['LR','RC'].map(type=>{const all=attempts.filter(a=>questions.find(q=>q.id===a.id).type===type),list=all.filter(a=>state.reviewFilter!=='Missed'||!a.correct);return `<article class="card review-set"><div class="review-heading"><div><div class="eyebrow">${all[0].date} · ${type==='LR'?'Logical Reasoning':'Reading Comprehension'}</div><h2>${type==='LR'?'Causes, conditions and evidence':'Scope and purpose'}</h2></div><p>${all.filter(a=>a.correct).length} of ${all.length} correct</p></div><div class="answer-strip" aria-label="${type} question results">${list.map(a=>{const q=questions.find(q=>q.id===a.id);return `<button class="${a.correct?'':'missed'}" data-action="revisit" data-id="${a.id}" aria-label="${q.title}, ${a.correct?'correct':'missed'}, revisit exact question">Q${q.number} <span aria-hidden="true">${a.correct?'✓':'↗'}</span></button>`;}).join('')}</div>${list.map(a=>{const q=questions.find(q=>q.id===a.id);return `<div class="review-row"><div><span class="result-label ${a.correct?'':'missed'}">${a.correct?'Correct':'Missed · revisit'}</span><h3>${q.title}</h3><p class="ref">${reference(q)}</p><p class="synthetic-note">Synthetic question, not the real PT${q.pt} item.</p></div><button data-action="revisit" data-id="${q.id}">${a.correct?'Revisit':'Try again'} ${ico('arrow')}</button></div>`;}).join('')}</article>`;}).join('')}<p class="hint">Fixed demonstration records. Practising these questions does not change this sample history.</p>`;}
  function progress(){const lr=attempts.filter(a=>questions.find(q=>q.id===a.id).type==='LR').length,rc=attempts.length-lr;return `${intro('Your classroom','Progress','The same fixed records shown in Review. No score prediction or mastery claim.')}<section class="metrics"><article class="metric"><span class="eyebrow">Completed sets</span><strong>${totals.sets}</strong><p>${attemptDateRange}</p></article><article class="metric"><span class="eyebrow">Questions answered</span><strong>${totals.answered}</strong><p>${lr} Logical Reasoning · ${rc} Reading Comprehension</p></article><article class="metric"><span class="eyebrow">Correct answers</span><strong>${totals.correct}<span class="metric-denominator"> / ${totals.answered}</span></strong><p>${totals.answered-totals.correct} questions available for review.</p></article></section><section class="card saved-place"><div class="eyebrow">Your saved place</div><h2>Negation Station</h2><p class="dialog-copy">5 of 12 statements complete. Your next statement is 6.</p>${statementTrack()}<div class="inline-actions section-space"><button class="primary" data-action="continue">Continue from statement 6 ${ico('arrow')}</button><a class="text-link" href="#review">Review your results ${ico('arrow')}</a></div></section>`;}
  const libraryItems={Lessons:[['Conditional language','Follow the signal words and preserve the complete condition.','12 min read'],['The conclusion and its support','Identify what the author wants you to believe, and why.','8 min read']],Activities:[['Negation Station','Practise saying the opposite without changing the subject of the statement.','12 statements'],['Reading recall','Read one paragraph, recall it, then compare your account with the source.','At your own pace']],Bootcamps:[['Conditional Indicators Refresher','A focused return to sufficient and necessary conditions.','4 short lessons'],['Argument foundations','Connect evidence, conclusions and the gap between them.','3 short lessons']]};
  function library(){return `${intro('Your classroom','Library','Lessons, activities and bootcamps. Find question references in Practice.')}<div class="tabs" role="tablist" aria-label="Library content">${Object.keys(libraryItems).map(t=>`<button role="tab" aria-selected="${state.library===t}" tabindex="${state.library===t?0:-1}" data-action="library-tab" data-value="${t}">${t}</button>`).join('')}</div><section class="library-grid" role="tabpanel" aria-label="${state.library}">${libraryItems[state.library].map(([title,desc,meta],i)=>`<article class="card library-card"><div class="eyebrow">${state.library} · ${meta}</div><h2>${title}</h2><p>${desc}</p><button data-action="library-preview" data-index="${i}">Preview ${ico('arrow')}</button></article>`).join('')}</section>`;}
  function messages(){return `${intro('Your classroom','Messages','A note from your coach, and room to ask a question.')}<section class="message-page"><div class="card coach">${coachMessage()}</div><form id="draft-form" class="card draft-box"><h2>Your reply to Joshua</h2><p class="hint">Local draft only. Nothing is sent from this preview.</p><label for="message-draft">Message</label><textarea id="message-draft" name="draft" placeholder="Write your question or update…">${esc(state.workingDraft)}</textarea><div class="draft-actions"><button class="primary" type="submit">Save draft</button><span class="draft-status" id="draft-status" aria-live="polite">${state.draftSaveError?'Could not save. Your draft is still here; copy it before leaving this browser.':state.draftDirty?'Unsaved changes':state.draft?'Draft saved on this browser':''}</span></div></form></section>`;}
  function teacher(){return `${intro('Teacher preview','Your teaching day','Sample operations for Joshua. Student messages and assignments stay in their own workspace.')}<div class="two-col"><section class="card"><div class="eyebrow">Next session · October 26</div><h2>Ada Williams</h2><p class="dialog-copy">7:15 p.m. Eastern · 60 minutes<br>Focus: conditional language and negation.</p><button data-action="student" data-name="Ada Williams">Open student overview ${ico('arrow')}</button></section><section class="card"><div class="eyebrow">Before the session</div><h2>Keep the work in view</h2><p class="dialog-copy">Ada has 4 assigned items. Negation Station has a saved place at statement 6.</p><button data-action="assign" data-name="Ada Williams">Draft an assignment ${ico('arrow')}</button></section></div><section class="section-space"><h2 class="section-title">Upcoming sessions</h2>${teacherTable(students)}</section><p class="teacher-note">All students and sessions here are sample data. Drafting an assignment does not assign or notify anyone.</p>`;}
  function teacherTable(list){return list.length?`<div class="table-scroll card" role="region" aria-label="Student sessions" tabindex="0"><table class="table"><thead><tr><th>Student</th><th>Next session · 2026</th><th>Focus</th><th><span class="sr-only">Action</span></th></tr></thead><tbody>${list.map(s=>`<tr><td>${s.name}<br><span class="quiet">${s.work}</span></td><td>${s.next}</td><td>${s.focus}</td><td><button data-action="student" data-name="${s.name}" aria-label="View ${s.name}">View ${ico('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No sample students match. Search by name or focus, such as “Ada” or “reading”.</div>';}
  function studentPage(){return `${intro('Teacher preview','Students','Find a sample student and see the work to prepare.')}<div class="question-search">${ico('search')}<label class="sr-only" for="student-query">Search students by name or focus</label><input id="student-query" placeholder="Search by name or focus" value="${esc(state.studentQuery)}"></div><div id="student-results" aria-live="polite">${teacherTable(students.filter(s=>(s.name+' '+s.focus).toLowerCase().includes(state.studentQuery.toLowerCase())))}</div>`;}
  function reading(){return `${intro('Reading Center','Reading Center','Work through one paragraph at a time. Recall the meaning before you return to the text.')}<section class="library-grid"><article class="card library-card"><div class="eyebrow">Reading activity</div><h2>Reading recall</h2><p>Read a paragraph, recall it in your own words, then compare your account with the source.</p><button data-action="assignment" data-id="recall">Preview activity ${ico('arrow')}</button></article><article class="card library-card"><div class="eyebrow">Original sample paragraph</div><h2>Scope of the main point</h2><p>Read a short passage about a changing river, then identify its main point.</p><button data-action="question" data-id="rc155">Open sample ${ico('arrow')}</button></article></section>`;}
  const routes={home,work,practice,review,progress,library,messages,reading,teacher,students:studentPage};

  function render(focus=true){let r=currentRoute();if(!Object.hasOwn(routes,r)||(state.role==='teacher'&&!['teacher','students'].includes(r))||(state.role==='student'&&['teacher','students'].includes(r))){location.hash=state.role==='teacher'?'teacher':'home';return;}main.dataset.route=r;main.innerHTML=`<div class="page${focus?' route-transition':''}">${routes[r]()}${storageWarning()}${footer()}</div>`;renderNav();document.title=`${$('#page-title')?.textContent||'Classroom'} · LSAT U`;if(focus){$('#page-title')?.focus({preventScroll:true});window.scrollTo(0,0);$('#announcer').textContent=`${$('#page-title')?.textContent} page`;}if(r==='home')$('#agenda').setAttribute('aria-labelledby',`day-${state.day}`);}
  function route(r){if(currentRoute()===r)render();else location.hash=r;}

  // Dialogs. Any textarea carrying data-saved is compared with its saved value; Escape asks once before closing unsaved text.
  function modalDirty(){return [...modal.querySelectorAll('textarea[data-saved]')].some(t=>t.value!==t.dataset.saved);}
  function openDialog(title,body,actions=''){const wasOpen=modal.open;if(!wasOpen)dialogTrigger=document.activeElement;escArmed=false;modal.innerHTML=`<div class="dialog-head"><h2 id="modal-title" tabindex="-1">${title}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${ico('close')}</button></div>${body}${actions?`<div class="dialog-actions">${actions}</div>`:''}`;if(!wasOpen)modal.showModal();else $('#modal-title').focus();}
  function closeDialog(){modal.close();}
  function openQuestion(id){const q=questions.find(q=>q.id===id);if(!q)return;state.question=id;state.answer=null;state.checked=false;const recent=[id,...state.recent.filter(x=>x!==id)].slice(0,5);if(!save({recent})){state.recent=recent;}route('practice');}
  function finder(){state.question=null;state.questionTab='All';state.query='';if(drawer.open)drawer.close();route('practice');setTimeout(()=>$('#question-query')?.focus(),50);}

  document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();main.focus();return;}const button=e.target.closest('[data-action]');if(!button)return;const a=button.dataset.action,id=button.dataset.id;
    if(a==='finder'){e.preventDefault();finder();}
    if(a==='quick-practice'){const timed=button.dataset.mode==='timed';openDialog(timed?'Timed section setup':'Smart Drill setup',`<p class="dialog-copy">${timed?'Choose the section you want to practise.':'Choose the kind of question you want to practise.'}</p><form id="practice-setup-form"><label for="setup-type">Section</label><select id="setup-type" name="type"><option value="LR">Logical Reasoning</option><option value="RC">Reading Comprehension</option></select><p class="hint">This local design preview opens one original sample question. It does not generate a full drill or start a timed section.</p><div class="dialog-actions"><button type="button" data-action="close">Cancel</button><button type="submit" class="primary">Open sample question</button></div></form>`);}
    if(a==='menu'){dialogTrigger=button;drawer.innerHTML=`<button class="drawer-close icon-button" data-action="drawer-close" aria-label="Close navigation">${ico('close')}</button>${navHTML(true)}`;drawer.showModal();}
    if(a==='drawer-close')drawer.close();
    if(a==='close')closeDialog();
    if(a==='assignment'){e.preventDefault();const item=assignments.find(x=>x.id===id);openDialog(item.title,`<div class="dialog-reference">${item.detail} · Assigned sample</div><p class="dialog-copy">${item.description}</p><div class="workflow-box"><strong>${item.status}</strong><p class="hint">This is an assignment preview, not the full activity. Your saved resume task stays Negation Station.</p></div>`,`<button data-action="close">Close</button><button class="primary" data-action="go-work">View My Work ${ico('arrow')}</button>`);}
    if(a==='go-work'){closeDialog();route('work');}
    if(a==='continue'){const kept=state.negationWorking;openDialog('Negation Station',`<div class="dialog-reference">Saved place · Statement 6 of 12</div><p class="dialog-copy">Write the opposite of the statement. Change only what you need to make it false.</p><div class="workflow-box statement-box"><h3>Some of the books are illustrated.</h3><p>Your previous five statements are complete.</p></div><label for="negation-answer">Your rewrite</label><textarea id="negation-answer" data-saved="" placeholder="Write the opposite in your own words…">${esc(kept||'')}</textarea>${kept?'<p class="hint restored">Your unsaved rewrite from earlier is restored. It is kept only while this preview stays open.</p>':''}<p class="hint">A sample of the resume experience. This does not submit work to LSAT U. Compare your rewrite with a sample when you are ready; this preview does not judge your text.</p><div id="negation-feedback" aria-live="polite"></div>`,`<button data-action="close">Close preview</button><button class="primary" data-action="negation-check">Show sample answer</button>`);}
    if(a==='negation-check'){const val=$('#negation-answer').value.trim();$('#negation-feedback').innerHTML=val?'<div class="feedback"><strong>Sample answer</strong><p>None of the books are illustrated.</p><p>“Some” says that at least one book in this group is illustrated. To make that statement false, no book in that same group can be illustrated. “Some are not illustrated” could be true at the same time as the original, so it does not contradict it.</p><p>Compare the meaning of your rewrite with this sample. Your wording has not been graded.</p></div>':'<p class="error">Write your rewrite first, then compare it with the sample answer.</p>';}
    if(a==='read'){if(save({read:true})){render(false);$('[data-action="reply"]')?.focus();toast('Message marked as read.');}else toast('The message remains unread because this browser could not save the change.');}
    if(a==='reply'){route('messages');setTimeout(()=>$('#message-draft')?.focus(),50);}
    if(a==='prepare'){e.preventDefault();const kept=state.noteWorking;openDialog('Prepare for your session',`<div class="dialog-reference">October 26, 2026 · 7:15 p.m. Eastern</div><p class="dialog-copy">What would you like to work through with Joshua?</p><form id="note-form"><label for="session-note">Your preparation note</label><textarea id="session-note" name="note" data-saved="${esc(state.note)}">${esc(kept!==null?kept:state.note)}</textarea>${kept!==null?'<p class="hint restored">Your unsaved text from earlier is restored. Save to keep it.</p>':''}<p class="hint">Saved on this browser only. Your coach cannot see it.</p><div id="note-status" aria-live="polite"></div><div class="dialog-actions"><button type="button" data-action="close">Cancel</button><button type="submit" class="primary">Save note</button></div></form>`);}
    if(a==='day')selectDay(Number(button.dataset.day));
    if(a==='work-filter'){state.workFilter=button.dataset.value;render(false);$(`[data-action="work-filter"][data-value="${state.workFilter}"]`).focus();}
    if(a==='question'||a==='revisit'||a==='sample-reference')openQuestion(id);
    if(a==='question-type'){state.questionType=button.dataset.value;render(false);$('[data-action="question-type"][data-value="'+state.questionType+'"]').focus();}
    if(a==='review-filter'){state.reviewFilter=button.dataset.value;render(false);$('[data-action="review-filter"][data-value="'+state.reviewFilter+'"]').focus();}
    if(a==='work-status'){state.workStatus=button.dataset.value;render(false);$('[data-action="work-status"][data-value="'+state.workStatus+'"]').focus();}
    if(a==='question-back'){state.question=null;render();}
    if(a==='question-tab'){state.questionTab=button.dataset.value;render(false);$(`[data-action="question-tab"][data-value="${state.questionTab}"]`).focus();}
    if(a==='bookmark'){const list=state.bookmarks.includes(id)?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];if(save({bookmarks:list})){render(false);$('[data-action="bookmark"]').focus();toast(list.includes(id)?'Question saved on this browser.':'Question removed from saved questions.');}else toast('Saved questions could not be updated. The previous saved state is unchanged.');}
    if(a==='retry'){state.checked=false;$('#answer-feedback').innerHTML='';$('.answer input')?.focus();}
    if(a==='library-tab'){state.library=button.dataset.value;render(false);$(`[data-action="library-tab"][data-value="${state.library}"]`).focus();}
    if(a==='library-preview'){const [title,desc]=libraryItems[state.library][Number(button.dataset.index)];openDialog(title,`<div class="dialog-reference">${state.library} · Content preview</div><p class="dialog-copy">${desc}</p><p class="hint">The full lesson is outside this local design preview.</p>`,`<button data-action="close">Close preview</button>`);}
    if(a==='student'){const s=students.find(x=>x.name===button.dataset.name);openDialog(s.name,`<div class="dialog-reference">Sample student overview</div><h3>${s.focus}</h3><p class="dialog-copy">${s.work} · Next session ${s.next}, 2026<br>${s.name==='Ada Williams'?'Negation Station: 5 of 12 statements complete.':'Prepare one example about the student’s focus before the next session.'}</p><div class="workflow-box"><strong>Session preparation</strong><p>${s.name==='Ada Williams'?'Check the saved negation rewrite, then review the conditional refresher. One sample coach note is awaiting a reply.':'Review the assigned work and ask which step needs another example.'}</p></div>`,`<button data-action="close">Close</button><button class="primary" data-action="assign" data-name="${s.name}">Draft assignment</button>`);}
    if(a==='assign'){openDialog('Draft an assignment',`<div class="dialog-reference">Teacher preview · ${esc(button.dataset.name)}</div><form id="assignment-form"><label for="assign-title">Assignment</label><select id="assign-title"><option>Conditional Indicators Refresher</option><option>Negation Station</option><option>Reading recall</option></select><div class="field"><label for="assign-note">Instructions for the student</label><textarea id="assign-note" data-saved="" placeholder="Add a short note about what to pay attention to…"></textarea></div><p class="hint">Preview draft only. Nothing is assigned, sent or saved to a student account.</p><div id="assignment-status" aria-live="polite"></div><div class="dialog-actions"><button type="button" data-action="close">Cancel</button><button type="submit" class="primary">Preview assignment draft</button></div></form>`);}
  });
  document.addEventListener('input',e=>{if(modal.contains(e.target)){escArmed=false;$('#modal-guard')?.remove();}if(e.target.id==='work-query'){state.workQuery=e.target.value;$('#work-results').innerHTML=assignmentRows(workResults());}if(e.target.id==='question-query'){state.query=e.target.value;$('#question-results').innerHTML=resultsHTML(filteredQuestions());}if(e.target.id==='student-query'){state.studentQuery=e.target.value;$('#student-results').innerHTML=teacherTable(students.filter(s=>(s.name+' '+s.focus).toLowerCase().includes(state.studentQuery.toLowerCase())));}if(e.target.id==='message-draft'){state.workingDraft=e.target.value;state.draftDirty=state.workingDraft!==state.draft;state.draftSaveError=false;$('#draft-status').textContent=state.draftDirty?'Unsaved changes':state.draft?'Draft saved on this browser':'';}});
  document.addEventListener('change',e=>{if(e.target.dataset.action==='role'){state.role=e.target.value;save({role:state.role});state.question=null;if(drawer.open)drawer.close();route(state.role==='teacher'?'teacher':'home');}if(e.target.name==='answer'){state.answer=Number(e.target.value);state.checked=false;$('#answer-feedback').innerHTML='';}});
  function parseReference(text){const m=text.trim().match(/^(?:PT|PrepTest)?\s*0*(\d+)(?:\s*[·,/]\s*(?:S(?:ection)?\s*)?|\s*S(?:ection)?\s*|\s+)0*(\d+)(?:\s*[·,/]\s*(?:Q(?:uestion)?\s*)?|\s*Q(?:uestion)?\s*|\s+)0*(\d+)$/i);return m?m.slice(1).map(n=>String(Number(n))):null;}
  document.addEventListener('submit',e=>{e.preventDefault();const form=e.target;
    if(form.id==='practice-setup-form'){const type=new FormData(form).get('type');closeDialog();openQuestion(type==='RC'?'rc155':'lr155');}
    if(form.id==='typed-reference-form'){const value=$('#typed-reference').value.trim(),parts=parseReference(value),match=parts&&questions.find(q=>q.pt===parts[0]&&q.section===parts[1]&&q.number===parts[2]);if(match)openQuestion(match.id);else $('#typed-reference-feedback').innerHTML=value?`<span class="error">${esc(value)} is not one of the five sample references. Enter a reference such as PT155 S1 Q1 or 155 / 1 / 1. No different question was substituted.</span>`:'<span class="error">Enter a reference such as PT155 S1 Q1 or 155 / 1 / 1.</span>';}
    if(form.id==='reference-form'){const data=new FormData(form);const parts=['pt','section','number'].map(name=>String(data.get(name)||'').trim());const valid=parts.every(value=>/^\d+$/.test(value));const normalized=valid?parts.map(value=>value.replace(/^0+(?=\d)/,'')):[];const match=valid&&questions.find(q=>q.type===data.get('type')&&q.pt===normalized[0]&&q.section===normalized[1]&&q.number===normalized[2]);if(match)openQuestion(match.id);else $('#reference-feedback').innerHTML='<p class="error">Enter decimal digits only in each field, such as 155, 1 and 1. Leading zeros are accepted. That reference is not included in this local preview; use one of the five sample references listed below. No different question has been substituted.</p>';}
    if(form.id==='answer-form'){if(state.answer===null)return;state.checked=true;$('#answer-feedback').innerHTML=feedbackHTML(questions.find(q=>q.id===state.question));}
    if(form.id==='note-form'){const field=$('#session-note'),note=field.value;if(save({note})){field.dataset.saved=note;state.noteWorking=null;closeDialog();render(false);$('[data-action="prepare"]')?.focus();toast('Preparation note saved on this browser.');}else $('#note-status').innerHTML='<p class="error">Could not save the note locally. Your text is still here. Keep this dialog open or copy the note before closing.</p>';}
    if(form.id==='draft-form'){const draft=$('#message-draft').value;if(save({draft})){state.workingDraft=draft;state.draftDirty=false;state.draftSaveError=false;$('#draft-status').textContent='Draft saved on this browser. Nothing sent.';toast('Reply draft saved locally.');}else {state.workingDraft=draft;state.draftDirty=true;state.draftSaveError=true;$('#draft-status').textContent='Could not save. Your text is still in this field. Copy it before leaving.';}}
    if(form.id==='assignment-form'){$('#assignment-status').innerHTML=`<div class="feedback"><strong>Draft preview</strong><p>${esc($('#assign-title').value)}</p><p>${esc($('#assign-note').value||'No additional instructions.')}</p><p class="hint">Not assigned or sent. This draft lasts only while the dialog stays open.</p></div>`;}
  });
  document.addEventListener('keydown',e=>{
    if(e.target.matches('[data-action="library-tab"]')&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const names=Object.keys(libraryItems),i=names.indexOf(state.library);state.library=e.key==='Home'?names[0]:e.key==='End'?names.at(-1):names[(i+(e.key==='ArrowLeft'?-1:1)+names.length)%names.length];render(false);$('[data-action="library-tab"][data-value="'+state.library+'"]').focus();}
    if((applePlatform?e.metaKey&&!e.ctrlKey:e.ctrlKey&&!e.metaKey)&&!e.altKey&&!e.shiftKey&&e.key.toLowerCase()==='k'&&state.role==='student'&&!modal.open){e.preventDefault();finder();}
    // The week list is vertical on wide and phone layouts and horizontal in between, so both arrow axes move the selection.
    if(e.target.matches('.day')&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key)){e.preventDefault();const back=e.key==='ArrowLeft'||e.key==='ArrowUp';selectDay(e.key==='Home'?24:e.key==='End'?30:Math.max(24,Math.min(30,state.day+(back?-1:1))));}
  });
  modal.addEventListener('cancel',e=>{if(escArmed||!modalDirty())return;e.preventDefault();escArmed=true;let guard=$('#modal-guard');if(!guard){guard=document.createElement('p');guard.id='modal-guard';guard.className='guard';guard.setAttribute('role','alert');$('.dialog-head',modal).after(guard);}guard.textContent=$('#assign-note',modal)?'This draft has unsaved text. Press Escape again to discard it, or keep working.':'You have unsaved text. Press Escape again to close. Your text is kept for this visit, but it is not saved.';});
  modal.addEventListener('close',()=>{const note=$('#session-note',modal),rewrite=$('#negation-answer',modal);if(note)state.noteWorking=note.value!==note.dataset.saved?note.value:null;if(rewrite)state.negationWorking=rewrite.value.trim()?rewrite.value:null;escArmed=false;dialogTrigger?.focus?.();});
  drawer.addEventListener('click',e=>{if(e.target.closest('a[href^="#"]'))drawer.close();});
  drawer.addEventListener('close',()=>dialogTrigger?.focus?.());
  window.addEventListener('hashchange',()=>{if(currentRoute()!=='practice'){state.question=null;}render();});
  window.LSATPreview=Object.freeze({inspect:()=>JSON.parse(JSON.stringify({...state,route:currentRoute()})),attempts:attempts.map(a=>({...a})),totals:{...totals},references:questions.map(q=>({id:q.id,ref:reference(q),type:q.type}))});
  render(false);
})();
